theorem gapBlocked_iff_common_singleton
    {A B : Set α} (hA : A.Nonempty) (hB : B.Nonempty) :
    GapBlocked A B ↔ ∃ t, A = {t} ∧ B = {t}

theorem residualSupport_subset_basis_sdiff
    (M : Matroid α) {D : Set α} {t e : α}
    (hD : M.IsBase D) (heE : e ∈ M.E) (heD : e ∉ D) :
    ResidualSupport M D t e ⊆ D \ {t}

theorem fundamentalSupport_eq_singleton_of_residualSupport_eq_empty
    (M : Matroid α) {D : Set α} {t e : α}
    (ht : t ∈ FundamentalSupport M D e)
    (hres : ResidualSupport M D t e = ∅) :
    FundamentalSupport M D e = {t}

@[simp] theorem rankTwoWoven_false
    {α : Type*}
    {M : Matroid α}
    {k m : ℕ}
    (D : RankTwoSortedEnumeration M k m)
    (hk : 0 < k)
    (i : Fin k) :
    rankTwoWoven D hk (i, false) =
      D.y (firstIndex k i)

@[simp] theorem rankTwoWoven_true
    {α : Type*}
    {M : Matroid α}
    {k m : ℕ}
    (D : RankTwoSortedEnumeration M k m)
    (hk : 0 < k)
    (i : Fin k) :
    rankTwoWoven D hk (i, true) =
      D.y (secondIndex k i)

theorem rankTwoWoven_successor_ne
    {α : Type*}
    {M : Matroid α}
    {k m : ℕ}
    (D : RankTwoSortedEnumeration M k m)
    (hk : 0 < k)
    (p : Fin k × Bool) :
    rankTwoWoven D hk p ≠
      rankTwoWoven D hk (weaveNext k hk p)

theorem rankTwoWoven_successor_coe_ne
    {α : Type*}
    {M : Matroid α}
    {k m : ℕ}
    (D : RankTwoSortedEnumeration M k m)
    (hk : 0 < k)
    (p : Fin k × Bool) :
    ((rankTwoWoven D hk p : M.E) : α) ≠
      ((rankTwoWoven D hk (weaveNext k hk p) : M.E) : α)

theorem eq_pair_of_disjoint_members
    {F : Finset (Finset (Fin 6))}
    (hF : LinearTripleFamily6 F)
    {A B : Finset (Fin 6)}
    (hAF : A ∈ F) (hBF : B ∈ F)
    (hAB : A ≠ B)
    (hdisj : Disjoint A B) :
    F = {A, B}

theorem avoidingCycle6_mono
    {F G : Finset (Finset (Fin 6))}
    (hFG : F ⊆ G)
    {a b c d e f : Fin 6}
    (h : AvoidingCycle6 G a b c d e f) :
    AvoidingCycle6 F a b c d e f

theorem pairIntersection_point_ne_of_three_distinct
    {F : Finset (Finset (Fin 6))}
    (hF : LinearTripleFamily6 F)
    {A B C : Finset (Fin 6)}
    (hAF : A ∈ F) (hBF : B ∈ F) (hCF : C ∈ F)
    (hAB : A ≠ B) (hAC : A ≠ C) (hBC : B ≠ C)
    {p q : Fin 6}
    (hp : p ∈ A ∩ B) (hq : q ∈ C) :
    p ≠ q
